# Submit column-sorted-asc
response = {"action": "submit", "grid": [[2, 1, 0], [4, 7, 3], [6, 8, 9]]}
print("Submitting col-sorted-asc:", response)

# Try the Zen/Z-order reading
grid = [
    [6, 1, 0],
    [4, 8, 9],
    [2, 7, 3]
]

# Z-order: row 0 left-right, row 1 right-left, row 2 left-right, etc.
z_order_read = []
for i in range(3):
    if i % 2 == 0:
        z_order_read.extend(grid[i])
    else:
        z_order_read.extend(grid[i][::-1])
print("Z-order read:", z_order_read)

# Sort and write back in Z-order
sorted_z = sorted(z_order_read)
# Fill back
for i in range(3):
    if i % 2 == 0:
        for j in range(3):
            grid[i][j] = sorted_z[i*3 + j]
    else:
        for j in range(2, -1, -1):
            grid[i][j] = sorted_z[i*3 + j]

print("Grid after Z-order sort:", grid)

# Also just try simple column-by-column fill with sorted values
flat = sorted([cell for row in grid for cell in row])
col_fill = [flat[i*3:(i+1)*3] for i in range(3)]
print("Column-fill with sorted flat:", col_fill)
response = {"action": "submit", "grid": col_fill}
print("Submitting:", response)

